const today = new Date();
const out = [];
const WINDOWS = [
  { days: 90, alert_type: 'vat_return_due_90d', qa_priority: 'low' },
  { days: 60, alert_type: 'vat_return_due_60d', qa_priority: 'low' },
  { days: 30, alert_type: 'vat_return_due_30d', qa_priority: 'normal' },
  { days: 7,  alert_type: 'vat_return_due_7d',  qa_priority: 'high' }
];
for (const r of items.map(i => i.json)) {
  if (!r.due_date) continue;
  const due = new Date(r.due_date);
  const diffDays = Math.floor((due - today) / (1000*60*60*24));
  for (const w of WINDOWS) {
    if (diffDays === w.days) {
      out.push({ json: {
        customer_id: r.customer_id,
        return_id: r.id,
        alert_type: w.alert_type,
        qa_priority: w.qa_priority,
        trigger_date: today.toISOString().slice(0,10),
        dedup_key: r.id + ':' + w.alert_type,
        customer_email: r.vat_customers && r.vat_customers.contact_email,
        customer_legal_name: r.vat_customers && r.vat_customers.legal_name,
        customer_vrn: r.vat_customers && r.vat_customers.vat_number,
        payload: { days_to_due: w.days, due_date: r.due_date, period_label: r.period_label, stagger: r.stagger, mtd_status: r.mtd_status }
      } });
    }
  }
}
return out;
